<template>
  <el-drawer :model-value="modelValue" :title="`${categoryLabel} · 月份对账`" size="min(920px, 96vw)" @close="close">
    <div class="monthly-toolbar"><el-date-picker v-model="month" type="month" value-format="YYYY-MM" format="YYYY年MM月" placeholder="选择月份"/><el-select v-if="available.length" :model-value="month" aria-label="已有月份" @change="month=$event"><el-option v-for="item in available" :key="item" :label="item" :value="item"/></el-select><el-select v-model="tab" aria-label="对账内容"><el-option label="单据" value="documents"/><el-option label="付款" value="payments"/></el-select><span>{{partyName||'全部往来单位'}}</span></div>
    <el-alert v-if="error" :title="error" type="error" :closable="false"/>
    <div v-if="summary" class="monthly-metrics"><div><small>月期初应付额</small><strong>{{money(summary.opening_payable)}}</strong></div><button class="metric-button" @click="selectPayments"><small>本月付款额 · 查看付款</small><strong>{{money(summary.paid_amount)}}</strong></button><div><small>剩余应付</small><strong>{{money(summary.remaining_amount)}}</strong></div><div><small>本月新增应付</small><strong>{{money(summary.new_payable)}}</strong></div><div><small>定金抵扣</small><strong>{{money(summary.applied_amount)}}</strong></div><div><small>历史已付</small><strong>{{money(summary.historical_paid_amount)}}</strong></div><div><small>期初预付 / 超付</small><strong>{{money(summary.opening_credit)}}</strong></div><div><small>期末预付 / 超付</small><strong>{{money(summary.credit_balance)}}</strong></div><div><small>待核对应付的本月付款</small><strong>{{money(summary.unknown_payment_amount)}}</strong></div></div>
    <p v-if="summary" class="hint">待核对 {{summary.unknown_documents||0}} 张 · 缺少日期 {{summary.undated_documents||0}} 张。该汇总基于当前可识别单据；缺少日期或待核对项目可能影响月份归属。</p><p v-for="notice in notices" :key="notice" class="hint">{{notice}}</p><el-alert v-if="downloadError" :title="downloadError" type="error" :closable="false"/>
    <el-table :data="rows" v-loading="loading" border empty-text="当前范围没有记录">
      <template v-if="tab==='documents'"><el-table-column label="单号" min-width="190"><template #default="{row}"><el-button link type="primary" @click="emit('open',{kind:row.kind,id:row.id,number:row.number})">{{row.number}}</el-button><small class="party">{{row.party_name}}</small></template></el-table-column><el-table-column label="单据时间" min-width="155"><template #default="{row}">{{formatDocumentTime(row.document_time)||'未记录'}}</template></el-table-column><el-table-column v-for="f in documentMoneyFields" :key="f" :prop="f" :label="balanceLabel(f)" min-width="115"><template #default="{row}">{{money(row[f])}}</template></el-table-column><el-table-column prop="unknown_reason" label="待核对原因" min-width="160"/></template>
      <template v-else><el-table-column label="付款日期" width="120"><template #default="{row}">{{formatDocumentTime(row.date)||'未记录'}}<el-tag v-if="row.date_inferred" type="warning" size="small">账期月末推定</el-tag></template></el-table-column><el-table-column label="单位 / 付款单号" min-width="190"><template #default="{row}">{{row.party_name}} · {{row.number}}<el-tag v-if="row.is_reversal" size="small" type="warning">冲销</el-tag></template></el-table-column><el-table-column label="金额" width="130"><template #default="{row}">{{money(row.amount)}}</template></el-table-column><el-table-column label="参考号 / 备注" min-width="170"><template #default="{row}">{{row.reference_number||'—'}}<p class="hint">{{row.notes?.split('\n')[0]||''}}</p></template></el-table-column><el-table-column label="原始转账凭据" min-width="220"><template #default="{row}"><template v-if="row.vouchers?.length"><span v-for="file in row.vouchers" :key="file.id" class="voucher"><el-button link type="primary" @click="preview(row,file)">{{file.file_name}}</el-button><el-button link @click="download(row,file)">下载</el-button></span></template><span v-else class="muted">待补转账凭据</span></template></el-table-column></template>
    </el-table><el-pagination :current-page="page" :total="count" :page-size="20" layout="total,prev,pager,next" @current-change="changePage"/>
    <el-dialog v-model="previewOpen" title="原始转账凭据" width="min(900px, 94vw)" @closed="releasePreview"><img v-if="previewType.startsWith('image/')" :src="previewUrl" class="preview-image"/><iframe v-else-if="previewType==='application/pdf'" :src="previewUrl" class="preview-pdf" title="转账凭据 PDF"/><p v-else>该文件格式不支持在线预览，请下载查看。</p></el-dialog>
  </el-drawer>
</template>
<script setup>
import {computed, onUnmounted, ref, watch} from 'vue';
import {fetchMonthlyPayables} from '../../api/supplyDashboardV2';
import {fetchApiFile, downloadApiFile} from '../../api/request';
import {paymentVoucherUrl} from '../../api/supplyCostsV2';
import {useAuthStore} from '../../stores/auth';
import {cockpitActorKey} from '../../utils/cockpitDraft';
import {formatDocumentTime} from '../../utils/supplyDocumentTime';
const props=defineProps({modelValue:Boolean,queue:{type:String,default:'supplier'},countryId:[String,Number],partyId:[String,Number],partyName:String});
const categoryLabel=computed(()=>({supplier:'供应商货款',domestic:'国内运费',carrier:'批次货运费',clearance:'入库清关费用',deposit:'采购定金'})[props.queue]);
const emit=defineEmits(['update:modelValue','open']);
const auth=useAuthStore(), month=ref(shanghaiMonth()),tab=ref('documents'),rows=ref([]),summary=ref(null),count=ref(0),available=ref([]),notices=ref([]),loading=ref(false),error=ref(''),downloadError=ref(''),page=ref(1);
let generation=0,previewGeneration=0;const previewUrl=ref(''),previewType=ref(''),previewOpen=ref(false);
function shanghaiMonth(){const parts=new Intl.DateTimeFormat('en',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).formatToParts(new Date());return `${parts.find(p=>p.type==='year').value}-${parts.find(p=>p.type==='month').value}`;}
const money=v=>v==null?'待核对':Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:4});
const documentMoneyFields=['opening_payable','new_payable','paid_amount','applied_amount','historical_paid_amount','remaining_amount','credit_balance'];
function balanceLabel(k){return ({opening_payable:'期初应付',new_payable:'新增应付',paid_amount:'已付',applied_amount:'抵扣',historical_paid_amount:'历史已付',remaining_amount:'剩余应付',credit_balance:'期末预付 / 超付'})[k]||k;}
function selectPayments(){if(tab.value!=='payments'){tab.value='payments';page.value=1;}}
function close(){emit('update:modelValue',false);}
async function load(){const token=++generation;rows.value=[];summary.value=null;count.value=0;available.value=[];notices.value=[];error.value='';if(!props.modelValue||auth.authorizationStale||!month.value){loading.value=false;return;}loading.value=true;const params={queue:props.queue,month:month.value,view:tab.value,limit:20,offset:(page.value-1)*20,...(props.countryId?{country_id:props.countryId}:{}),...(props.partyId?{party_id:props.partyId}:{})};try{const r=await fetchMonthlyPayables(params);if(token!==generation)return;if(!r?.success)throw new Error(r?.message||'月份对账读取失败');const d=r.data||{};rows.value=d.rows||[];summary.value=d.summary||null;count.value=Number(d.count||0);available.value=d.available_months||[];notices.value=d.notices||[];}catch(e){if(token===generation)error.value=e.message||'月份对账读取失败';}finally{if(token===generation)loading.value=false;}}
function changePage(v){page.value=v;load();}
function fileUrl(row,file){return paymentVoucherUrl(row.kind,row.source_id,row.voucher_payment_id||row.id,file.id);}
async function preview(row,file){const token=++previewGeneration;try{const result=await fetchApiFile(fileUrl(row,file));if(token!==previewGeneration)return;if(!result?.success||!result.blob)throw new Error(result?.message||'凭据读取失败');releasePreview();previewType.value=file.content_type||result.blob.type||'';previewUrl.value=URL.createObjectURL(new Blob([result.blob],{type:previewType.value}));previewOpen.value=true;}catch(e){if(token===previewGeneration)error.value=e.message||'凭据读取失败';}}
async function download(row,file){downloadError.value='';try{const result=await downloadApiFile(fileUrl(row,file),file.file_name);if(result?.success===false)throw new Error(result.message||'凭据下载失败');}catch(e){downloadError.value=e.message||'凭据下载失败';}}
function releasePreview(){previewOpen.value=false;if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value='';previewType.value='';previewGeneration++;}
watch(()=>[props.modelValue,props.queue,props.countryId,props.partyId],()=>{page.value=1;downloadError.value='';generation++;previewOpen.value=false;releasePreview();load();},{immediate:true});
watch(()=>[month.value,tab.value],()=>{page.value=1;releasePreview();load();});
watch(()=>props.modelValue,open=>{if(!open){generation++;rows.value=[];summary.value=null;available.value=[];notices.value=[];loading.value=false;previewOpen.value=false;releasePreview();}});
watch(()=>[cockpitActorKey(auth.currentUser),auth.authorizationStale],()=>{generation++;rows.value=[];summary.value=null;available.value=[];notices.value=[];loading.value=false;previewOpen.value=false;releasePreview();if(!auth.authorizationStale)load();},{flush:'sync'});
onUnmounted(()=>{generation++;releasePreview();});
</script>
<style scoped>.monthly-toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:16px}.monthly-toolbar .el-select{width:120px}.monthly-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.monthly-metrics>div,.metric-button{padding:12px;background:#f5f7fb;border-radius:6px}.metric-button{border:0;text-align:left;cursor:pointer;color:inherit;font:inherit}.monthly-metrics small,.monthly-metrics strong{display:block}.monthly-metrics strong{margin-top:7px;overflow-wrap:anywhere}.party{display:block;color:#64748b}.voucher{display:flex;align-items:center;gap:4px}.muted,.hint{color:#64748b}.preview-image{max-width:100%;max-height:75vh;display:block;margin:auto}.preview-pdf{width:100%;height:75vh;border:0}@media(max-width:640px){.monthly-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
